<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\ArchiveRecord;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ArchiveAdminController extends Controller {
 public function index(){return view('admin.legacy.archive',['items'=>ArchiveRecord::latest()->paginate(100)]);}
 public function import(Request $r){$r->validate(['file'=>'required|file|max:10240']);$xml=@simplexml_load_file($r->file('file')->getRealPath());if(!$xml||!isset($xml->spec))return back()->withErrors(['file'=>'Не удалось прочитать legacy XML']);$spec=$xml->spec;DB::transaction(function()use($spec){$programLegacy=(int)$spec['num'];ArchiveRecord::create(['legacy_id'=>$programLegacy,'type'=>'program_snapshot','title'=>(string)$spec['name'],'started_at'=>(string)$spec['din']?:null,'ended_at'=>(string)$spec['dout']?:null,'data'=>['hours'=>(int)$spec['specchas'],'specialty'=>(string)$spec['specs']]]);foreach($spec->student as $s){$scores=[];foreach($s->ball as $b)$scores[]=['subject'=>(string)$b['predm'],'score'=>(int)$b['otc'],'hours'=>(int)$b['chas']];$extra=[];foreach($s->dopsv as $v)$extra[]=['name'=>(string)$v['nazv'],'type'=>(int)$v['typ'],'string'=>(string)$v['valstr'],'int'=>(string)$v['valint'],'date'=>(string)$v['valdat']];ArchiveRecord::create(['legacy_id'=>(int)$s['num'],'type'=>'student_snapshot','title'=>trim((string)$s['fam'].' '.(string)$s['name'].' '.(string)$s['otch']),'data'=>['program_legacy_id'=>$programLegacy,'final_work'=>(string)$s['itog_rab'],'red_registry'=>(string)$s['krasn_reg'],'registration_number'=>(string)$s['nreg'],'issue_date'=>(string)$s['datav'],'protocol'=>(string)$s['protocol'],'scores'=>$scores,'extra'=>$extra]]);}});return back()->with('ok','Архивный XML импортирован');}
}
